<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<title>Diário Oficial - Agosto 1891</title>
<style>
  body {
    font-family: "Times New Roman", Georgia, serif;
    font-size: 13px;
    line-height: 1.4;
    max-width: 1100px;
    margin: 20px auto;
    padding: 20px;
    background: #f5f0e8;
    color: #1a1a1a;
  }
  .header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px double #000;
    padding-bottom: 5px;
