    font-size: 14px;
  }
  .header .page-num { font-size: 16px; }
  .header .title { font-size: 18px; letter-spacing: 3px; }
  .header .date { font-size: 14px; }
  .columns {
    display: flex;
    gap: 20px;
  }
  .column {
    flex: 1;
    text-align: justify;
    hyphens: auto;
  }
  .column p {
    margin: 0 0 8px 0;
    text-indent: 1em;
  }
  .section-title {
    text-align: center;
    font-weight: bold;
    font-size: 15px;
    margin: 15px 0 10px 0;
    border-top: 1px solid #000;
    border-bottom: 1px solid #000;
    padding: 5px 0;
  }
  .subsection-title {
    text-align: center;
    font-weight: bold;
    font-size: 13px;
    margin: 12px 0 8px 0;
    letter-spacing: 1px;
  }
  .separator {
    text-align: center;
    margin: 10px 0;
    font-size: 18px;
    letter-spacing: 5px;
  }
  .signature {
    font-style: italic;
    margin-top: 5px;
  }
